def walk(o,path=''):
    if isinstance(o,dict):
        for k,v in o.items(): yield from walk(v,path+'/'+str(k))
    elif isinstance(o,list):
        for i,v in enumerate(o): yield from walk(v,path+f'[{i}]')
    else:
        yield path,o
